import itertools
import numpy as np

def count_cliques(n, adj_matrix, k):
    """Counts the number of k-cliques in a graph defined by an adjacency matrix."""
    count = 0
    vertices = range(n)
    for subset in itertools.combinations(vertices, k):
        is_clique = True
        # Check every pair within the subset
        for i_idx, j_idx in itertools.combinations(range(k), 2):
            u = subset[i_idx]
            v = subset[j_idx]
            # Check adjacency: adj_matrix[u, v] must be 1
            if adj_matrix[u, v] == 0:
                is_clique = False
                break
        if is_clique:
            count += 1
    return count

def calculate_ratio(n, adj_matrix):
    f = count_cliques(n, adj_matrix, 3)
    g = count_cliques(n, adj_matrix, 4)
    if f == 0:
        return float('inf') if g > 0 else 0.0
    return (g**3) / (f**4)

